function shiftChar(ch, k){
  var c=ch.charCodeAt(0);
  if(c>=65&&c<=90) return String.fromCharCode((c-65+k+260)%26+65);
  if(c>=97&&c<=122) return String.fromCharCode((c-97+k+260)%26+97);
  return ch;
}
function caesar(text, shift, decrypt){
  var k=decrypt?-shift:shift;
  return String(text).replace(/[a-zA-Z]/g, function(m){ return shiftChar(m,k); });
}
function normalizeKey(key){ return String(key).toUpperCase().replace(/[^A-Z]/g,''); }
function vigenere(text, key, decrypt){
  key=normalizeKey(key); if(!key) key='A';
  var ki=0;
  return String(text).replace(/[a-zA-Z]/g, function(m){
    var base = (m<='Z')?65:97;
    var kc = key.charCodeAt(ki%key.length)-65; ki++;
    var ch = m.charCodeAt(0)-base;
    var n = decrypt ? (ch-kc+26)%26 : (ch+kc)%26;
    return String.fromCharCode(n+base);
  });
}
function rot13(text){ return caesar(text,13,false); }
function atbash(text){
  return String(text).replace(/[a-zA-Z]/g, function(m){
    var c=m.charCodeAt(0);
    if(c>=65&&c<=90) return String.fromCharCode(90-(c-65));
    return String.fromCharCode(122-(c-97));
  });
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { caesar:caesar, vigenere:vigenere, rot13:rot13, atbash:atbash, normalizeKey:normalizeKey };
}
